            return;
        const normalized = filename.split(path.sep).join('/');
        const extension = path.extname(normalized).toLowerCase();
        const manifest = isPackageManifestPath(normalized);
        if (category === 'docsConfig' || manifest) {
            if (await this.reload())
                this.schedule(manifest);
            else
                this.reportIslandProblems();
            return;
        }
        if (!this.enabled)
            return;
        if (category === 'mintIgnore') {
            await this.writeProps();
            this.collectPending = true;
            this.schedule(true);
            return;
        }
        if (category === 'page') {
            await this.recollect((collector) => collector.updatePage(normalized));
            this.schedule(false);
            return;
        }
        if (category === 'snippet-v2' ||
            (category === 'snippet' && PAGE_EXTENSIONS.has(extension)) ||
            Object.prototype.hasOwnProperty.call(this.collected?.snippetFiles ?? {}, `/${normalized}`)) {
            try {
                await this.recollect();
            }
            finally {
                this.schedule(true);
            }
            return;
        }
        this.reportIslandProblems();
        const file = `/${normalized.toLowerCase()}`;
