        const built = this.adopted?.manifest.islands ?? {};
        const collectedIds = this.collected.islands.map((island) => island.id);
        const islands = {};
        for (const id of [...collectedIds, ...this.listedIds, ...Object.keys(built)]) {
            if (Object.prototype.hasOwnProperty.call(islands, id))
                continue;
            const html = Object.prototype.hasOwnProperty.call(built, id) ? built[id]?.html : undefined;
            const css = Object.prototype.hasOwnProperty.call(built, id) ? built[id]?.css : undefined;
            islands[id] = {
                prefix: islandPrefixFor(id),
                ...(html !== undefined && { html }),
                ...(css !== undefined && { css }),
            };
        }
        for (const id of collectedIds)
            this.listedIds.add(id);
        const tmp = `${target}.${process.pid}.tmp`;
        const props = {
            buildId,
            islands,
            packageNames: [...this.setup.packageNames].sort(),
            packageSnippets: [...this.collected.packageSnippets].sort(),
            css: this.adopted?.manifest.css ?? [],
        };
        await fse.outputFile(tmp, JSON.stringify(props));
