        if (previousCollector)
            this.collector.inheritSnippetTrees(previousCollector);
        await this.recollect();
        const namesChanged = !previous || !sameSet(previous.packageNames, setup.packageNames);
        const snippetsChanged = !previousSnippets || !sameSet(previousSnippets, this.collected?.packageSnippets ?? new Set());
        if (!initial && (namesChanged || snippetsChanged))
            await this.importOptionsChanged();
