        this.finishTracking(changed, [...result.localFiles, ...result.missingLocalFiles]);
        if (this.buildingInputKey !== inputKey) {
            await fse.remove(tmpDir);
            return;
        }
        const diagnostics = result.manifest.diagnostics;
        const errors = diagnostics.filter((d) => d.level === 'error');
        const warnings = diagnostics.filter((d) => d.level === 'warning').map(formatDiagnostic);
